567	      var word = svg.dataset.word;
568	      Array.prototype.forEach.call(mask.querySelectorAll('.hull'), function(n){ n.remove(); });
569	      var fam = getComputedStyle(text).fontFamily;
570	      for (var i=0; i<word.length; i++){
571	        var ch = word[i];
572	        if ('AUX'.indexOf(ch) < 0) continue;
573	        var pen;
574	        try { pen = text.getStartPositionOfChar(i).x; } catch(e){ continue; }
575	        var r = inkScan(ch, fam);
576	        var polys = ch === 'X' ? r.polyRows.concat(r.polyCols) : r.polyRows;
577	        polys.forEach(function(pts){
578	          var el = document.createElementNS(NS, 'polygon');
579	          el.setAttribute('points', pts); el.setAttribute('fill', '#fff'); el.setAttribute('class', 'hull');
580	          el.setAttribute('transform', 'translate(' + pen + ' ' + BASE + ')');
581	          mask.appendChild(el);
582	        });
583	      }
584	    });
585	  }
586	
587	  /* ---------------- signaturakten: papperet glider, raderna glider isär ---------------- */
588	  var heroAct = document.getElementById('heroAct');
589	  var block = document.getElementById('block');
590	  var strips = [document.getElementById('strip1'), document.getElementById('strip2')];
591	  var siteRow = document.getElementById('siteRow');
592	  var siteNames = ['Exempelsida: Calyx, florist i Stockholm', 'Exempelsida: Hōrai, Asian fusion-koncept', 'Exempelsida: Hyperborea, konferens i Lund'];
593	  var siteIdx = -1;
594	
595	  var clamp = function(v,a,b){ return Math.min(b, Math.max(a, v)); };
596	  var lerp = function(a,b,t){ return a + (b-a)*t; };
597	  var smooth = function(t){ t = clamp(t,0,1); return t*t*(3-2*t); };
598	  var stepEase = function(t){ t = clamp(t,0,1); return t*t*(3-2*t); };
599	
600	  /* Byte: p 0.06–0.58, två övergångar med vila. Isärglidning: p 0.62–0.84, ett
601	     tydligt steg (raderna glider isär via transform, aldrig opacitet på
602	     bokstäverna) som sedan håller till p 1. Rubrikens två rader reser sig
603	     staggrat inom samma fönster (kinetic lines). */
604	  function stripPos(ps){
605	    var seg = [[0.12,0.42],[0.58,0.88]];
606	    var k = 0;
607	    seg.forEach(function(pair){ k += smooth(clamp((ps - pair[0]) / (pair[1] - pair[0]), 0, 1)); });
608	    return k;
609	  }
610	
611	  var forced = null;
612	  if (preview === 'calyx') forced = 0;
613	  else if (preview === 'horai') forced = 0.34;
614	  else if (preview === 'hyperborea') forced = 0.55;
615	  else if (preview === 'open') forced = 1;
616	
617	  var target = 0, cur = 0;
618	
619	  function apply(p){
620	    var byte = clamp((p - 0.06) / (0.58 - 0.06), 0, 1);
621	    var k = stripPos(byte);
622	    strips.forEach(function(strip){ strip.setAttribute('transform', 'translate(0 ' + (-k * 234) + ')'); });
623	    var idx = clamp(Math.round(k), 0, 2);
624	    if (idx !== siteIdx){ siteIdx = idx; siteRow.textContent = siteNames[idx]; }
625	
626	    var openT = clamp((p - 0.62) / (0.84 - 0.62), 0, 1);
627	    var open = stepEase(openT);
628	    block.style.setProperty('--open', open.toFixed(4));
629	
630	    /* rubriken väntar tills gapet faktiskt öppnat sig (annars hinner den
631	       hägra mot bokstäverna innan de separerat, se runda 3 F-002-liknande fynd) */
632	    var l1 = stepEase(clamp((openT - 0.3) / 0.5, 0, 1));
633	    var l2 = stepEase(clamp((openT - 0.5) / 0.5, 0, 1));
634	    block.style.setProperty('--l1', l1.toFixed(4));
635	    block.style.setProperty('--l2', l2.toFixed(4));
636	  }
637	
638	  function frame(){
639	    cur += (target - cur) * 0.15;
640	    if (Math.abs(target - cur) < 0.0004) cur = target;
641	    apply(cur);
642	    if (cur !== target) requestAnimationFrame(frame);
643	  }
644	
645	  var raf = false;
646	  function onScroll(){
647	    if (forced !== null || skipScroll) return;
648	    var top = heroAct.offsetTop;
649	    var travel = Math.max(heroAct.offsetHeight - innerHeight, 1);
650	    target = clamp((scrollY - top) / travel, 0, 1);
651	    if (!raf){ raf = true; requestAnimationFrame(function(){ frame(); raf = false; }); }
652	  }
653	
654	  /* ---- bilder som inte kom fram hämtas om (utvecklingsservrar tappar anslutningar ibland) ---- */
655	  document.querySelectorAll('img, image').forEach(function(el){
656	    var tries = 0;
657	    el.addEventListener('error', function(){
658	      if (tries++ >= 3) return;
659	      var isSvg = el.tagName.toLowerCase() === 'image';
660	      var src = isSvg ? el.getAttribute('href') : el.getAttribute('src');
661	      var clean = src.split('?')[0];
662	      setTimeout(function(){ if (isSvg) el.setAttribute('href', clean + '?r=' + tries); else el.src = clean + '?r=' + tries; }, 350 * tries);
663	    });
664	  });
665	
666	  /* ---- bild två och tre i heroAct:s fönster hämtas efter den första, i tur och ordning ---- */
667	  function loadStripRest(){
668	    var pending = Array.prototype.slice.call(document.querySelectorAll('svg image[data-href]'));
669	    (function next(){ var el = pending.shift(); if (!el) return; el.setAttribute('href', el.dataset.href); el.removeAttribute('data-href'); setTimeout(next, 120); })();
670	  }
671	  var firstStrip = document.querySelector('svg image[href]');
672	  if (firstStrip){ var done = false; var go = function(){ if (!done){ done = true; loadStripRest(); } }; firstStrip.addEventListener('load', go); firstStrip.addEventListener('error', go); setTimeout(go, 1500); }
673	
674	  function init(){
675	    buildWindows();
676	    if (forced !== null){
677	      target = forced; cur = forced; apply(forced);
678	    } else if (skipScroll){
679	      apply(0);
680	    } else {
681	      onScroll();
682	    }
683	  }
684	
685	  addEventListener('scroll', onScroll, { passive:true });
686	  addEventListener('resize', function(){ if (forced === null && !skipScroll) onScroll(); });
687	  init();
688	  if (document.fonts && document.fonts.load){
689	    Promise.all([document.fonts.load('900 100px Archivo'), document.fonts.load('400 16px "Familjen Grotesk"')])
690	      .then(function(){ buildWindows(); if (forced !== null) apply(forced); else if (!skipScroll) onScroll(); })
691	      .catch(function(){});
692	  }
693	})();
694	</script>
695	<script>ScrollCraft.mount(document.body);</script>
696	</body>
